     3→import { useMemo, useSyncExternalStore } from "react";
     4→
     5→export const SOUND_CLOUD_PROFILE_URL = "https://soundcloud.com/loic-ghanem";
     6→export const SOUND_CLOUD_TRACKS_URL = `${SOUND_CLOUD_PROFILE_URL}/tracks`;
     7→
     8→// Embed the full public catalogue (tracks page) instead of a limited playlist.
     9→export const SOUND_CLOUD_PLAYLIST_EMBED_URL = `https://w.soundcloud.com/player/?url=${encodeURIComponent(
    10→  SOUND_CLOUD_TRACKS_URL
    11→)}&color=%23000000&auto_play=false&hide_related=true&show_comments=false&show_user=true&show_reposts=false&show_teaser=false`;
    12→
    13→export type GlobalAudioPlayerStatus = "idle" | "loading" | "ready" | "error";
    14→
    15→export type GlobalAudioTrack = {
    16→  id: number;
    17→  title: string;
    18→  artist?: string;
    19→  artworkUrl?: string | null;
    20→  waveformUrl?: string | null;
    21→  permalinkUrl?: string | null;
    22→  durationMs?: number;
    23→  widgetIndex?: number;
    24→};
    25→
    26→export type GlobalAudioPlayerState = {
    27→  status: GlobalAudioPlayerStatus;
    28→  mediaAllowed: boolean;
    29→  hasStarted: boolean;
    30→  isDismissed: boolean;
    31→  isPlaying: boolean;
    32→  track: GlobalAudioTrack | null;
    33→  queue: GlobalAudioTrack[];
    34→  currentIndex: number | null;
    35→  positionMs: number;
    36→  durationMs: number;
    37→  volume: number;
    38→  error: string | null;
    39→};
    40→
    41→const VOLUME_STORAGE_KEY = "loic-player-volume-v1";
    42→
    43→const DEFAULT_STATE: GlobalAudioPlayerState = {
    44→  status: "idle",
    45→  mediaAllowed: false,
    46→  hasStarted: false,
    47→  isDismissed: false,
    48→  isPlaying: false,
    49→  track: null,
    50→  queue: [],
    51→  currentIndex: null,
    52→  positionMs: 0,
    53→  durationMs: 0,
    54→  volume: 80,
    55→  error: null,
    56→};
    57→
    58→let state: GlobalAudioPlayerState = DEFAULT_STATE;
    59→const listeners = new Set<() => void>();
    60→
    61→const emit = () => {
    62→  listeners.forEach((listener) => listener());
    63→};
    64→
    65→const setState = (
    66→  partial:
    67→    | Partial<GlobalAudioPlayerState>
    68→    | ((prev: GlobalAudioPlayerState) => Partial<GlobalAudioPlayerState>)
    69→) => {
    70→  const patch = typeof partial === "function" ? partial(state) : partial;
    71→  state = { ...state, ...patch };
    72→  emit();
    73→};
    74→
    75→export const getGlobalAudioPlayerState = () => state;
    76→
    77→export const subscribeGlobalAudioPlayer = (listener: () => void) => {
    78→  listeners.add(listener);
    79→  return () => listeners.delete(listener);
    80→};
    81→
    82→type PendingActionType = "play" | "toggle";
    83→type PendingAction =
    84→  | { type: PendingActionType; requestedAt: number }
    85→  | { type: "select"; requestedAt: number; widgetIndex: number }
    86→  | null;
    87→
    88→const PENDING_ACTION_TTL_MS = 15000;
    89→let pendingAction: PendingAction = null;
    90→
    91→let widget: SoundCloudWidget | null = null;
    92→
    93→let hasHydratedVolume = false;
    94→
    95→const clampVolume = (value: number) => {
    96→  if (!Number.isFinite(value)) return DEFAULT_STATE.volume;
    97→  return Math.max(0, Math.min(100, Math.round(value)));
    98→};
    99→
   100→export const hydrateGlobalAudioPlayerVolume = () => {
   101→  if (hasHydratedVolume) return;
   102→  hasHydratedVolume = true;
   103→  try {
   104→    const raw = localStorage.getItem(VOLUME_STORAGE_KEY);
   105→    if (!raw) return;
   106→    const parsed = Number.parseInt(raw, 10);
   107→    if (!Number.isFinite(parsed)) return;
   108→    setState({ volume: clampVolume(parsed) });
   109→  } catch {
   110→    // localStorage not available
   111→  }
   112→};
   113→
   114→export const setGlobalAudioPlayerMediaAllowed = (mediaAllowed: boolean) => {
   115→  setState(() => ({
   116→    mediaAllowed,
   117→    ...(mediaAllowed ? null : { status: "idle", isPlaying: false, positionMs: 0 }),
   118→    ...(mediaAllowed ? null : { error: null }),
   119→  }));
   120→};
   121→
   122→export const setGlobalAudioPlayerStatus = (status: GlobalAudioPlayerStatus) => {
   123→  setState({ status });
   124→};
   125→
   126→export const setGlobalAudioPlayerError = (error: string | null) => {
   127→  setState({
   128→    error,
   129→    ...(error ? { status: "error" } : null),
   130→  });
   131→};
   132→
   133→export const setGlobalAudioPlayerTrack = (track: GlobalAudioTrack | null) => {
   134→  setState((prev) => {
   135→    if (!track) {
   136→      return { track: null, positionMs: 0, durationMs: 0 };
   137→    }
   138→    const isNewTrack = prev.track?.id !== track.id;
   139→    return {
   140→      track,
   141→      ...(isNewTrack ? { positionMs: 0, durationMs: 0 } : null),
   142→    };
   143→  });
   144→};
   145→
   146→export const setGlobalAudioPlayerQueue = (queue: GlobalAudioTrack[]) => {
   147→  setState({ queue });
   148→};
   149→
   150→let hasFetchedFullQueue = false;
   151→let isFetchingQueue = false;
   152→
   153→type ApiTrack = {
   154→  id: number;
   155→  title: string;
   156→  artist?: string;
   157→  artworkUrl?: string | null;
   158→  waveformUrl?: string | null;
   159→  permalinkUrl?: string | null;
   160→  durationMs?: number;
   161→  widgetIndex?: number;
   162→};
   163→
   164→export const fetchFullSoundCloudQueue = async (): Promise<boolean> => {
   165→  if (hasFetchedFullQueue || isFetchingQueue) return hasFetchedFullQueue;
   166→
   167→  isFetchingQueue = true;
   168→  try {
   169→    const res = await fetch("/api/soundcloud/tracks");
   170→    if (!res.ok) {
   171→      isFetchingQueue = false;
   172→      return false;
   173→    }
   174→
   175→    const data = await res.json();
   176→    if (!data.tracks || !Array.isArray(data.tracks)) {
   177→      isFetchingQueue = false;
   178→      return false;
   179→    }
   180→
   181→    const currentState = getGlobalAudioPlayerState();
   182→    const widgetQueue = currentState.queue;
   183→
   184→    // Build a map of track ID to widget index for quick lookup
   185→    const widgetIndexMap = new Map<number, number>();
   186→    widgetQueue.forEach((wt) => {
   187→      if (typeof wt.widgetIndex === "number") {
   188→        widgetIndexMap.set(wt.id, wt.widgetIndex);
   189→      }
   190→    });
   191→
   192→    // Map API tracks and find widget indices by matching track IDs
   193→    const mappedTracks: GlobalAudioTrack[] = (data.tracks as ApiTrack[]).map((track) => {
   194→      const widgetIndex = widgetIndexMap.get(track.id);
   195→      return {
   196→        id: track.id,
   197→        title: track.title,
   198→        artist: track.artist,
   199→        artworkUrl: track.artworkUrl,
   200→        waveformUrl: track.waveformUrl,
   201→        permalinkUrl: track.permalinkUrl,
   202→        durationMs: track.durationMs,
   203→        // Only set widgetIndex if track is in widget's range (first 20)
   204→        widgetIndex: widgetIndex !== undefined ? widgetIndex : undefined,
   205→      };
   206→    });
   207→
   208→    setGlobalAudioPlayerQueue(mappedTracks);
   209→
   210→    // Update current index if we have a current track
   211→    const currentId = currentState.track?.id;
   212→    if (typeof currentId === "number") {
   213→      const idx = mappedTracks.findIndex((t) => t.id === currentId);
   214→      if (idx >= 0) setGlobalAudioPlayerCurrentIndex(idx);
   215→    } else if (mappedTracks.length > 0) {
   216→      // No track selected yet, set the first track as the current one
   217→      setGlobalAudioPlayerTrack(mappedTracks[0]);
   218→      setGlobalAudioPlayerCurrentIndex(0);
   219→    }
   220→
   221→    hasFetchedFullQueue = true;
   222→    isFetchingQueue = false;
   223→    return true;
   224→  } catch (error) {
   225→    // eslint-disable-next-line no-console
   226→    console.error("Failed to fetch SoundCloud tracks:", error);
   227→    isFetchingQueue = false;
   228→    return false;
   229→  }
   230→};
   231→
   232→export const resetFullQueueFetchState = () => {
   233→  hasFetchedFullQueue = false;
   234→  isFetchingQueue = false;
   235→};
   236→
   237→export const setGlobalAudioPlayerCurrentIndex = (currentIndex: number | null) => {
   238→  setState({ currentIndex });
   239→};
   240→
   241→export const setGlobalAudioPlayerProgress = (positionMs: number, durationMs?: number) => {
   242→  setState({
   243→    positionMs,
   244→    ...(typeof durationMs === "number" && durationMs > 0 ? { durationMs } : null),
   245→  });
   246→};
   247→
   248→export const setGlobalAudioPlayerPlaying = (isPlaying: boolean) => {
   249→  setState({ isPlaying });
   250→};
   251→
   252→export const markGlobalAudioPlayerStarted = () => {
   253→  setState({ hasStarted: true, isDismissed: false });
   254→};
   255→
   256→export const setGlobalAudioPlayerWidget = (nextWidget: SoundCloudWidget | null) => {
   257→  widget = nextWidget;
   258→};
   259→
   260→export const setGlobalAudioPlayerDismissed = (isDismissed: boolean) => {
   261→  setState({ isDismissed, ...(isDismissed ? null : { hasStarted: true }) });
   262→};
   263→
   264→export const setGlobalAudioPlayerVolume = (volume: number) => {
   265→  const clamped = clampVolume(volume);
   266→  setState({ volume: clamped });
   267→  try {
   268→    localStorage.setItem(VOLUME_STORAGE_KEY, clamped.toString());
   269→  } catch {
   270→    // localStorage not available
   271→  }
   272→  if (!widget || !state.mediaAllowed) return;
   273→  try {
   274→    widget.setVolume(clamped);
   275→  } catch {
   276→    // noop
   277→  }
   278→};
   279→
   280→export const queueGlobalAudioPlayerAction = (type: PendingActionType) => {
   281→  pendingAction = { type, requestedAt: Date.now() };
   282→};
   283→
   284→export const queueGlobalAudioPlayerSelectTrack = (widgetIndex: number) => {
   285→  pendingAction = {
   286→    type: "select",
   287→    widgetIndex: Math.max(0, Math.floor(widgetIndex)),
   288→    requestedAt: Date.now(),
   289→  };
   290→};
   291→
   292→export const tryConsumePendingGlobalAudioPlayerAction = () => {
   293→  if (!widget) return false;
   294→  if (!pendingAction) return false;
   295→  const isFresh = Date.now() - pendingAction.requestedAt <= PENDING_ACTION_TTL_MS;
   296→  const action = pendingAction;
   297→  pendingAction = null;
   298→  if (!isFresh) return false;
   299→
   300→  if (action.type === "select") {
   301→    try {
   302→      widget.skip(action.widgetIndex);
   303→      widget.play();
   304→      return true;
   305→    } catch {
   306→      return false;
   307→    }
   308→  }
   309→
   310→  if (action.type === "play") {
   311→    widget.play();
   312→    return true;
   313→  }
   314→  if (action.type === "toggle") {
   315→    widget.toggle();
   316→    return true;
   317→  }
   318→  return false;
   319→};
   320→
   321→const canControlWidget = () => !!widget && state.status === "ready" && state.mediaAllowed;
   322→
   323→const resolveCurrentIndex = () => {
   324→  if (typeof state.currentIndex === "number") return state.currentIndex;
   325→  const currentId = state.track?.id;
   326→  if (typeof currentId !== "number") return null;
   327→  const idx = state.queue.findIndex((t) => t.id === currentId);
   328→  return idx >= 0 ? idx : null;
   329→};
   330→
   331→export const globalAudioPlayerActions = {
   332→  play: () => {
   333→    markGlobalAudioPlayerStarted();
   334→    queueGlobalAudioPlayerAction("play");
   335→    if (!canControlWidget()) return;
   336→    widget?.play();
   337→  },
   338→  pause: () => {
   339→    if (!canControlWidget()) return;
   340→    widget?.pause();
   341→  },
   342→  setVolume: (volume: number) => {
   343→    setGlobalAudioPlayerVolume(volume);
   344→  },
   345→  toggle: () => {
   346→    markGlobalAudioPlayerStarted();
   347→    queueGlobalAudioPlayerAction("toggle");
   348→    if (!canControlWidget()) return;
   349→    widget?.toggle();
   350→  },
   351→  next: () => {
   352→    const { queue } = state;
   353→    const idx = resolveCurrentIndex();
   354→    if (queue.length && typeof idx === "number") {
   355→      globalAudioPlayerActions.selectTrack((idx + 1) % queue.length);
   356→      return;
   357→    }
   358→    if (!canControlWidget()) return;
   359→    widget?.next();
   360→  },
   361→  previous: () => {
   362→    const { queue } = state;
   363→    const idx = resolveCurrentIndex();
   364→    if (queue.length && typeof idx === "number") {
   365→      globalAudioPlayerActions.selectTrack((idx - 1 + queue.length) % queue.length);
   366→      return;
   367→    }
   368→    if (!canControlWidget()) return;
   369→    widget?.prev();
   370→  },
   371→  selectTrack: (index: number) => {
   372→    markGlobalAudioPlayerStarted();
   373→    const safeIndex = Math.max(0, Math.floor(index));
   374→    const boundedIndex =
   375→      state.queue.length > 0 ? Math.min(safeIndex, state.queue.length - 1) : safeIndex;
   376→    setGlobalAudioPlayerCurrentIndex(boundedIndex);
   377→    const nextTrack = state.queue[boundedIndex];
   378→    if (nextTrack) setGlobalAudioPlayerTrack(nextTrack);
   379→    setGlobalAudioPlayerProgress(0);
   380→
   381→    const widgetIndex = nextTrack?.widgetIndex;
   382→    const isInWidgetRange = typeof widgetIndex === "number" && widgetIndex >= 0 && widgetIndex < 20;
   383→
   384→    if (!canControlWidget()) {
   385→      // Queue action for when widget becomes ready
   386→      if (isInWidgetRange && typeof widgetIndex === "number") {
   387→        queueGlobalAudioPlayerSelectTrack(widgetIndex);
   388→      }
   389→      return;
   390→    }
   391→
   392→    try {
   393→      if (isInWidgetRange && typeof widgetIndex === "number") {
   394→        // Track is in widget's loaded range, use skip
   395→        widget?.skip(widgetIndex);
   396→        widget?.play();
   397→      } else if (nextTrack?.permalinkUrl) {
   398→        // Track is beyond widget range, load it directly
   399→        widget?.load(nextTrack.permalinkUrl, { auto_play: true });
   400→      }
   401→    } catch {
   402→      // noop
   403→    }
   404→  },
   405→  open: () => {
   406→    setGlobalAudioPlayerDismissed(false);
   407→  },
   408→  dismiss: () => {
   409→    setGlobalAudioPlayerDismissed(true);
   410→    setGlobalAudioPlayerPlaying(false);
   411→    try {
   412→      widget?.pause();
   413→    } catch {
   414→      // noop
   415→    }
   416→  },
   417→  seekTo: (milliseconds: number) => {
   418→    if (!canControlWidget()) return;
   419→    const clamped = Math.max(0, Math.floor(milliseconds));
   420→    widget?.seekTo(clamped);
   421→    setGlobalAudioPlayerProgress(clamped);
   422→  },
   423→  seekToRatio: (ratio: number) => {
   424→    if (!state.durationMs) return;
   425→    const clampedRatio = Math.max(0, Math.min(1, ratio));
   426→    globalAudioPlayerActions.seekTo(Math.floor(state.durationMs * clampedRatio));
   427→  },
   428→};
   429→
   430→export const useGlobalAudioPlayer = () => {
   431→  const snapshot = useSyncExternalStore(
   432→    subscribeGlobalAudioPlayer,
   433→    getGlobalAudioPlayerState,
   434→    getGlobalAudioPlayerState
   435→  );
   436→
   437→  return useMemo(
   438→    () => ({
   439→      ...snapshot,
   440→      actions: globalAudioPlayerActions,
   441→    }),
   442→    [snapshot]
   443→  );
   444→};
