    85→  const x = useMotionValue(0);
    86→  const y = useMotionValue(0);
    87→
    88→  const springX = useSpring(x, springConfig);
    89→  const springY = useSpring(y, springConfig);
    90→
    91→  useEffect(() => {
    92→    const element = ref.current;
    93→    if (!element) return;
    94→
    95→    const handleMouseMove = (e: MouseEvent) => {
    96→      const rect = element.getBoundingClientRect();
    97→      const centerX = rect.left + rect.width / 2;
    98→      const centerY = rect.top + rect.height / 2;
    99→
   100→      const distanceX = e.clientX - centerX;
   101→      const distanceY = e.clientY - centerY;
   102→
   103→      if (hoverOnly && !isHovered) {
   104→        x.set(0);
   105→        y.set(0);
   106→        return;
   107→      }
   108→
   109→      x.set(distanceX * strength);
   110→      y.set(distanceY * strength);
   111→    };
   112→
   113→    const handleMouseEnter = () => setIsHovered(true);
   114→    const handleMouseLeave = () => {
   115→      setIsHovered(false);
   116→      x.set(0);
   117→      y.set(0);
   118→    };
   119→
   120→    element.addEventListener('mouseenter', handleMouseEnter);
   121→    element.addEventListener('mouseleave', handleMouseLeave);
   122→    window.addEventListener('mousemove', handleMouseMove);
   123→
   124→    return () => {
   125→      element.removeEventListener('mouseenter', handleMouseEnter);
   126→      element.removeEventListener('mouseleave', handleMouseLeave);
   127→      window.removeEventListener('mousemove', handleMouseMove);
   128→    };
   129→  }, [x, y, strength, hoverOnly, isHovered]);
   130→
   131→  return { ref, x: springX, y: springY, isHovered };
   132→}
