   134→/* ============================================
   135→   3D CARD EFFECT HOOK
   136→   ============================================ */
   137→
   138→interface Use3DCardOptions {
   139→  /** Maximum rotation in degrees */
   140→  maxRotation?: number;
   141→  /** Perspective value */
   142→  perspective?: number;
   143→  /** Scale on hover */
   144→  scale?: number;
   145→  /** Spring configuration */
   146→  springConfig?: SpringOptions;
   147→}
   148→
   149→interface Use3DCardReturn {
   150→  ref: RefObject<HTMLDivElement | null>;
   151→  rotateX: MotionValue<number>;
   152→  rotateY: MotionValue<number>;
   153→  scale: MotionValue<number>;
   154→  isHovered: boolean;
   155→  style: {
   156→    rotateX: MotionValue<number>;
   157→    rotateY: MotionValue<number>;
   158→    scale: MotionValue<number>;
   159→    transformPerspective: number;
   160→  };
   161→}
   162→
   163→/**
   164→ * Hook for 3D card tilt effect on hover
   165→ *
   166→ * @example
   167→ * ```tsx
   168→ * const { ref, style } = use3DCard({ maxRotation: 15 });
   169→ *
   170→ * <motion.div ref={ref} style={style}>
   171→ *   3D Card Content
   172→ * </motion.div>
   173→ * ```
   174→ */
   175→export function use3DCard({
   176→  maxRotation = 15,
   177→  perspective = 1000,
   178→  scale: scaleValue = 1.05,
   179→  springConfig = { stiffness: 300, damping: 30 },
   180→}: Use3DCardOptions = {}): Use3DCardReturn {
   181→  const ref = useRef<HTMLDivElement>(null);
   182→  const [isHovered, setIsHovered] = useState(false);
   183→
   184→  const rotateXValue = useMotionValue(0);
   185→  const rotateYValue = useMotionValue(0);
   186→  const scaleMotion = useMotionValue(1);
   187→
   188→  const rotateX = useSpring(rotateXValue, springConfig);
   189→  const rotateY = useSpring(rotateYValue, springConfig);
   190→  const scale = useSpring(scaleMotion, springConfig);
   191→
   192→  useEffect(() => {
   193→    const element = ref.current;
   194→    if (!element) return;
   195→
   196→    const handleMouseMove = (e: MouseEvent) => {
   197→      if (!isHovered) return;
   198→
   199→      const rect = element.getBoundingClientRect();
   200→      const centerX = rect.left + rect.width / 2;
   201→      const centerY = rect.top + rect.height / 2;
   202→
   203→      const percentX = (e.clientX - centerX) / (rect.width / 2);
   204→      const percentY = (e.clientY - centerY) / (rect.height / 2);
   205→
   206→      rotateXValue.set(-percentY * maxRotation);
   207→      rotateYValue.set(percentX * maxRotation);
   208→    };
   209→
   210→    const handleMouseEnter = () => {
   211→      setIsHovered(true);
   212→      scaleMotion.set(scaleValue);
   213→    };
   214→
   215→    const handleMouseLeave = () => {
   216→      setIsHovered(false);
   217→      rotateXValue.set(0);
   218→      rotateYValue.set(0);
   219→      scaleMotion.set(1);
   220→    };
   221→
   222→    element.addEventListener('mouseenter', handleMouseEnter);
   223→    element.addEventListener('mouseleave', handleMouseLeave);
   224→    element.addEventListener('mousemove', handleMouseMove);
   225→
   226→    return () => {
   227→      element.removeEventListener('mouseenter', handleMouseEnter);
   228→      element.removeEventListener('mouseleave', handleMouseLeave);
   229→      element.removeEventListener('mousemove', handleMouseMove);
   230→    };
   231→  }, [rotateXValue, rotateYValue, scaleMotion, maxRotation, scaleValue, isHovered]);
   232→
   233→  return {
   234→    ref,
   235→    rotateX,
   236→    rotateY,
   237→    scale,
   238→    isHovered,
   239→    style: {
   240→      rotateX,
   241→      rotateY,
   242→      scale,
   243→      transformPerspective: perspective,
   244→    },
   245→  };
   246→}
