   248→/* ============================================
   249→   MOUSE GLOW EFFECT HOOK
   250→   ============================================ */
   251→
   252→interface UseMouseGlowOptions {
   253→  /** Size of the glow in pixels */
   254→  size?: number;
   255→  /** Color of the glow (CSS color) */
