   273→
   274→/**
   275→ * Hook for glow effect that follows mouse cursor
   276→ *
   277→ * @example
   278→ * ```tsx
   279→ * const { ref, glowStyle, isHovered } = useMouseGlow({ color: '#00f0ff' });
