   307→
   308→  useEffect(() => {
   309→    const element = ref.current;
   310→    if (!element) return;
   311→
   312→    const handleMouseMove = (e: MouseEvent) => {
   313→      const rect = element.getBoundingClientRect();
   314→      setPosition({
   315→        x: e.clientX - rect.left,
   316→        y: e.clientY - rect.top,
   317→      });
   318→    };
   319→
   320→    const handleMouseEnter = () => setIsHovered(true);
   321→    const handleMouseLeave = () => setIsHovered(false);
   322→
   323→    element.addEventListener('mouseenter', handleMouseEnter);
   324→    element.addEventListener('mouseleave', handleMouseLeave);
   325→    element.addEventListener('mousemove', handleMouseMove);
   326→
   327→    return () => {
   328→      element.removeEventListener('mouseenter', handleMouseEnter);
   329→      element.removeEventListener('mouseleave', handleMouseLeave);
