   347→/* ============================================
   348→   COUNT UP ANIMATION HOOK
   349→   ============================================ */
   350→
   351→interface UseCountUpOptions {
   352→  /** Starting value */
   353→  start?: number;
   354→  /** Ending value */
   355→  end: number;
   356→  /** Duration in seconds */
   357→  duration?: number;
   358→  /** Decimal places */
   359→  decimals?: number;
   360→  /** Prefix (e.g., "$") */
   361→  prefix?: string;
   362→  /** Suffix (e.g., "+", "%") */
   363→  suffix?: string;
   364→  /** Only start when in view */
   365→  startOnView?: boolean;
   366→  /** Easing function */
   367→  easing?: 'linear' | 'easeOut' | 'easeInOut';
   368→}
   369→
   370→interface UseCountUpReturn {
   371→  ref: RefObject<HTMLSpanElement | null>;
   372→  value: string;
   373→  isComplete: boolean;
   374→  reset: () => void;
   375→}
   376→
   377→/**
   378→ * Hook for animated count-up numbers
   379→ *
   380→ * @example
   381→ * ```tsx
   382→ * const { ref, value } = useCountUp({ end: 100, suffix: '+' });
   383→ *
   384→ * <span ref={ref}>{value}</span>
   385→ * ```
   386→ */
   387→export function useCountUp({
   388→  start = 0,
   389→  end,
   390→  duration = 2,
   391→  decimals = 0,
   392→  prefix = '',
   393→  suffix = '',
   394→  startOnView = true,
   395→  easing = 'easeOut',
   396→}: UseCountUpOptions): UseCountUpReturn {
   397→  const ref = useRef<HTMLSpanElement>(null);
   398→  const [currentValue, setCurrentValue] = useState(start);
   399→  const [isComplete, setIsComplete] = useState(false);
   400→  const [hasStarted, setHasStarted] = useState(false);
   401→
   402→  const isInView = useInView(ref, { once: true, margin: '-100px' });
   403→
   404→  const easingFunctions = {
   405→    linear: (t: number) => t,
   406→    easeOut: (t: number) => 1 - Math.pow(1 - t, 3),
   407→    easeInOut: (t: number) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2,
   408→  };
   409→
   410→  const reset = useCallback(() => {
   411→    setCurrentValue(start);
   412→    setIsComplete(false);
   413→    setHasStarted(false);
   414→  }, [start]);
   415→
   416→  useEffect(() => {
   417→    if (startOnView && !isInView) return;
   418→    if (hasStarted) return;
   419→
   420→    setHasStarted(true);
   421→    const startTime = Date.now();
   422→    const durationMs = duration * 1000;
   423→
   424→    const animate = () => {
   425→      const elapsed = Date.now() - startTime;
   426→      const progress = Math.min(elapsed / durationMs, 1);
   427→      const easedProgress = easingFunctions[easing](progress);
   428→
   429→      const value = start + (end - start) * easedProgress;
   430→      setCurrentValue(value);
   431→
   432→      if (progress < 1) {
   433→        requestAnimationFrame(animate);
   434→      } else {
   435→        setIsComplete(true);
   436→      }
   437→    };
   438→
   439→    requestAnimationFrame(animate);
   440→  }, [start, end, duration, easing, startOnView, isInView, hasStarted]);
   441→
   442→  const formattedValue = `${prefix}${currentValue.toFixed(decimals)}${suffix}`;
   443→
   444→  return { ref, value: formattedValue, isComplete, reset };
   445→}
   446→
   447→/* ============================================
   448→   STAGGER CHILDREN HOOK
   449→   ============================================ */
   450→
   451→interface UseStaggerOptions {
   452→  /** Delay between each child in seconds */
   453→  staggerDelay?: number;
   454→  /** Initial delay before first child */
   455→  initialDelay?: number;
   456→  /** Only trigger when in view */
   457→  triggerOnView?: boolean;
   458→}
   459→
   460→/**
   461→ * Hook for staggered animation delays
   462→ *
   463→ * @example
   464→ * ```tsx
   465→ * const { getDelay, isInView, ref } = useStagger({ staggerDelay: 0.1 });
   466→ *
   467→ * <div ref={ref}>
   468→ *   {items.map((item, index) => (
   469→ *     <motion.div
   470→ *       key={item.id}
   471→ *       initial={{ opacity: 0, y: 20 }}
   472→ *       animate={isInView ? { opacity: 1, y: 0 } : {}}
   473→ *       transition={{ delay: getDelay(index) }}
   474→ *     >
   475→ *       {item.content}
   476→ *     </motion.div>
   477→ *   ))}
   478→ * </div>
   479→ * ```
   480→ */
   481→export function useStagger({
   482→  staggerDelay = 0.1,
   483→  initialDelay = 0,
   484→  triggerOnView = true,
   485→}: UseStaggerOptions = {}) {
   486→  const ref = useRef<HTMLDivElement>(null);
   487→  const isInView = useInView(ref, { once: true, margin: '-50px' });
   488→
   489→  const getDelay = useCallback(
   490→    (index: number) => initialDelay + index * staggerDelay,
   491→    [initialDelay, staggerDelay]
   492→  );
   493→
   494→  const shouldAnimate = triggerOnView ? isInView : true;
   495→
   496→  return { ref, isInView, shouldAnimate, getDelay };
   497→}
   498→
   499→/* ============================================
   500→   SCROLL VELOCITY HOOK
   501→   ============================================ */
   502→
   503→interface UseScrollVelocityReturn {
   504→  velocity: number;
   505→  direction: 'up' | 'down' | 'none';
   506→}
   507→
   508→/**
   509→ * Hook to track scroll velocity and direction
   510→ */
   511→export function useScrollVelocity(): UseScrollVelocityReturn {
   512→  const [velocity, setVelocity] = useState(0);
   513→  const [direction, setDirection] = useState<'up' | 'down' | 'none'>('none');
   514→  const lastScrollY = useRef(0);
   515→  const lastTime = useRef(Date.now());
   516→
   517→  useEffect(() => {
   518→    const handleScroll = () => {
   519→      const currentTime = Date.now();
   520→      const currentScrollY = window.scrollY;
   521→
   522→      const timeDelta = currentTime - lastTime.current;
   523→      const scrollDelta = currentScrollY - lastScrollY.current;
   524→
   525→      if (timeDelta > 0) {
   526→        const newVelocity = Math.abs(scrollDelta / timeDelta) * 100;
   527→        setVelocity(newVelocity);
   528→
   529→        if (scrollDelta > 0) {
   530→          setDirection('down');
   531→        } else if (scrollDelta < 0) {
   532→          setDirection('up');
   533→        } else {
   534→          setDirection('none');
   535→        }
   536→      }
   537→
   538→      lastScrollY.current = currentScrollY;
   539→      lastTime.current = currentTime;
   540→    };
   541→
   542→    window.addEventListener('scroll', handleScroll, { passive: true });
   543→    return () => window.removeEventListener('scroll', handleScroll);
   544→  }, []);
   545→
   546→  return { velocity, direction };
   547→}
