   549→/* ============================================
   550→   REDUCED MOTION HOOK
   551→   ============================================ */
   552→
   553→/**
   554→ * Hook to detect user preference for reduced motion
   555→ */
   556→export function useReducedMotion(): boolean {
   557→  const [reducedMotion, setReducedMotion] = useState(false);
   558→
   559→  useEffect(() => {
   560→    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
   561→    setReducedMotion(mediaQuery.matches);
   562→
   563→    const handleChange = (e: MediaQueryListEvent) => {
   564→      setReducedMotion(e.matches);
   565→    };
   566→
   567→    mediaQuery.addEventListener('change', handleChange);
   568→    return () => mediaQuery.removeEventListener('change', handleChange);
   569→  }, []);
   570→
   571→  return reducedMotion;
   572→}
