   574→/* ============================================
   575→   INTERSECTION OBSERVER HOOK
   576→   ============================================ */
   577→
   578→interface UseIntersectionOptions {
   579→  threshold?: number | number[];
   580→  rootMargin?: string;
   581→  triggerOnce?: boolean;
   582→}
   583→
   584→/**
   585→ * Hook for intersection observer with more control
   586→ */
   587→export function useIntersection({
   588→  threshold = 0,
   589→  rootMargin = '0px',
   590→  triggerOnce = true,
   591→}: UseIntersectionOptions = {}) {
   592→  const ref = useRef<HTMLDivElement>(null);
   593→  const [isIntersecting, setIsIntersecting] = useState(false);
   594→  const [hasIntersected, setHasIntersected] = useState(false);
   595→
   596→  useEffect(() => {
   597→    const element = ref.current;
   598→    if (!element) return;
   599→
   600→    const observer = new IntersectionObserver(
   601→      ([entry]) => {
   602→        const isCurrentlyIntersecting = entry.isIntersecting;
   603→
   604→        if (triggerOnce) {
   605→          if (isCurrentlyIntersecting && !hasIntersected) {
   606→            setIsIntersecting(true);
   607→            setHasIntersected(true);
   608→          }
   609→        } else {
   610→          setIsIntersecting(isCurrentlyIntersecting);
   611→        }
   612→      },
   613→      { threshold, rootMargin }
   614→    );
   615→
   616→    observer.observe(element);
   617→    return () => observer.disconnect();
   618→  }, [threshold, rootMargin, triggerOnce, hasIntersected]);
   619→
   620→  return { ref, isIntersecting, hasIntersected };
   621→}
   622→
   623→/* ============================================
   624→   TYPED TEXT HOOK
   625→   ============================================ */
   626→
   627→interface UseTypedTextOptions {
   628→  /** Text to type */
   629→  text: string;
   630→  /** Speed in milliseconds per character */
   631→  speed?: number;
   632→  /** Delay before starting */
   633→  delay?: number;
   634→  /** Start when in view */
   635→  startOnView?: boolean;
   636→  /** Show cursor */
   637→  showCursor?: boolean;
   638→}
   639→
   640→/**
   641→ * Hook for typewriter text effect
   642→ *
   643→ * @example
   644→ * ```tsx
   645→ * const { displayText, isComplete, ref } = useTypedText({
   646→ *   text: 'Hello World',
   647→ *   speed: 50
   648→ * });
   649→ *
   650→ * <span ref={ref}>{displayText}</span>
   651→ * ```
   652→ */
   653→export function useTypedText({
   654→  text,
   655→  speed = 50,
   656→  delay = 0,
   657→  startOnView = true,
   658→  showCursor = true,
   659→}: UseTypedTextOptions) {
   660→  const ref = useRef<HTMLSpanElement>(null);
   661→  const [displayText, setDisplayText] = useState('');
   662→  const [isComplete, setIsComplete] = useState(false);
   663→  const [hasStarted, setHasStarted] = useState(false);
   664→
   665→  const isInView = useInView(ref, { once: true });
   666→
   667→  useEffect(() => {
   668→    if (startOnView && !isInView) return;
   669→    if (hasStarted) return;
   670→
   671→    const startTimeout = setTimeout(() => {
   672→      setHasStarted(true);
   673→      let currentIndex = 0;
   674→
   675→      const typeInterval = setInterval(() => {
   676→        if (currentIndex < text.length) {
   677→          setDisplayText(text.slice(0, currentIndex + 1));
   678→          currentIndex++;
   679→        } else {
   680→          clearInterval(typeInterval);
   681→          setIsComplete(true);
   682→        }
   683→      }, speed);
   684→
   685→      return () => clearInterval(typeInterval);
   686→    }, delay);
   687→
   688→    return () => clearTimeout(startTimeout);
   689→  }, [text, speed, delay, startOnView, isInView, hasStarted]);
   690→
   691→  const cursor = showCursor && !isComplete ? '|' : '';
   692→
   693→  return { ref, displayText: displayText + cursor, isComplete };
   694→}
