   707→  UseMouseGlowReturn,
   708→  UseCountUpOptions,
   709→  UseCountUpReturn,
   710→  UseStaggerOptions,
   711→  UseScrollVelocityReturn,
   712→  UseIntersectionOptions,
   713→  UseTypedTextOptions,
   714→};
