    35→      // Slow velocities for subtle movement
    36→      velocities[i3] = (Math.random() - 0.5) * 0.005;
    37→      velocities[i3 + 1] = (Math.random() - 0.5) * 0.005;
    38→      velocities[i3 + 2] = (Math.random() - 0.5) * 0.002;
